import java.io.IOException;
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.servlet.annotation.WebServlet;
import java.util.logging.Logger;

@WebServlet("/api/reports")
public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String sessionToken = req.getHeader("X-Session-Token");
        if (sessionToken == null || !validateSession(sessionToken)) {
            resp.sendError(401, "Unauthorized");
            return;
        }

        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String sortCol = req.getParameter("sort");
        String orgId = req.getParameter("org_id");

        // Input length validation
        if (reportType != null && reportType.length() > 64) {
            resp.sendError(400, "Invalid type parameter");
            return;
        }
        if (sortCol != null && sortCol.length() > 32) {
            resp.sendError(400, "Invalid sort parameter");
            return;
        }

        // Allowlist for report types
        if (reportType == null || !reportType.matches("^(summary|detail|audit|compliance)$")) {
            resp.sendError(400, "Unknown report type");
            return;
        }

        // Date range validation
        if (dateRange != null && !dateRange.matches("^\\d{4}-\\d{2}-\\d{2}_\\d{4}-\\d{2}-\\d{2}$")) {
            resp.sendError(400, "Invalid date range format");
            return;
        }

        // Build query - sortCol is validated by length but not by allowlist
        String query = buildReportQuery(reportType, dateRange, sortCol, orgId);
        log.info("Executing report query for org=" + orgId + " type=" + reportType);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            resp.setContentType("application/json");
            ServletOutputStream out = resp.getOutputStream();
            out.println("{");
            out.println("  \"results\": [");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.println(",");
                out.println("    {\"id\": " + rs.getInt("id") +
                    ", \"name\": \"" + rs.getString("name") +
                    "\", \"value\": " + rs.getDouble("value") + "}");
                first = false;
            }
            out.println("  ]");
            out.println("}");
        } catch (SQLException e) {
            log.warning("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    private String buildReportQuery(String type, String range, String sort, String orgId) {
        StringBuilder sb = new StringBuilder();
        sb.append("SELECT id, name, value FROM reports_").append(type);
        sb.append(" WHERE org_id = '").append(orgId).append("'");

        if (range != null) {
            String[] parts = range.split("_");
            sb.append(" AND created_at BETWEEN '").append(parts[0])
              .append("' AND '").append(parts[1]).append("'");
        }

        if (sort != null) {
            sb.append(" ORDER BY ").append(sort);
        } else {
            sb.append(" ORDER BY created_at DESC");
        }

        sb.append(" LIMIT 1000");
        return sb.toString();
    }

    private boolean validateSession(String token) {
        // Validates against session store
        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement ps = conn.prepareStatement(
                 "SELECT 1 FROM sessions WHERE token = ? AND expires_at > NOW()")) {
            ps.setString(1, token);
            return ps.executeQuery().next();
        } catch (SQLException e) {
            return false;
        }
    }
}
